#include "unity.h"

#include <math.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#include "pitch_detector.h"
#include "td_psola_autotune.h"

#define TEST_SAMPLE_RATE 48000U
#define TEST_SECONDS 2U
#define TEST_SAMPLES (TEST_SAMPLE_RATE * TEST_SECONDS)
#define TEST_PI 3.14159265358979323846f

static int16_t input_buffer[TEST_SAMPLES];
static int16_t output_buffer[TEST_SAMPLES];

static void generate_harmonic_voice(float f0_hz)
{
    for (size_t n = 0U; n < TEST_SAMPLES; ++n)
    {
        const float t = (float)n / (float)TEST_SAMPLE_RATE;
        float x = 0.0f;
        x += 9000.0f * sinf(2.0f * TEST_PI * f0_hz * t);
        x += 4500.0f * sinf(2.0f * TEST_PI * 2.0f * f0_hz * t + 0.2f);
        x += 2400.0f * sinf(2.0f * TEST_PI * 3.0f * f0_hz * t + 0.4f);
        x += 1200.0f * sinf(2.0f * TEST_PI * 4.0f * f0_hz * t + 0.6f);
        if (x > 32767.0f) x = 32767.0f;
        if (x < -32768.0f) x = -32768.0f;
        input_buffer[n] = (int16_t)lrintf(x);
    }
}

static float measure_pitch(const int16_t *samples, size_t count)
{
    PitchDetector detector;
    PitchDetector_Init(&detector);
    float pitch = 0.0f;
    float confidence = 0.0f;
    float last_good = 0.0f;

    size_t pos = 0U;
    while (pos < count)
    {
        size_t block = count - pos;
        if (block > 64U) block = 64U;
        if (PitchDetector_ProcessBlock(&detector, samples + pos, block, &pitch, &confidence)
            && (confidence > 0.70f))
        {
            last_good = pitch;
        }
        pos += block;
    }
    return last_good;
}

static int max_adjacent_jump(const int16_t *samples, size_t count)
{
    int max_jump = 0;
    for (size_t i = 1U; i < count; ++i)
    {
        int diff = (int)samples[i] - (int)samples[i - 1U];
        if (diff < 0) diff = -diff;
        if (diff > max_jump) max_jump = diff;
    }
    return max_jump;
}

void setUp(void) {}
void tearDown(void) {}

static void test_ChromaticTargetMaps445To440(void)
{
    TEST_ASSERT_FLOAT_WITHIN(0.2f, 440.0f, TdPsola_ChromaticTargetHz(445.0f));
}

static void test_SilenceRemainsSilent(void)
{
    memset(input_buffer, 0, sizeof(input_buffer));
    memset(output_buffer, 1, sizeof(output_buffer));
    TEST_ASSERT_EQUAL_INT(TD_PSOLA_STATUS_OK,
                          TdPsola_ProcessBuffer(input_buffer, output_buffer,
                                                TEST_SAMPLES, NULL, NULL));
    for (size_t i = 0U; i < TEST_SAMPLES; ++i)
        TEST_ASSERT_EQUAL_INT16(0, output_buffer[i]);
}

static void test_445HzVoiceMovesToward440(void)
{
    generate_harmonic_voice(445.0f);
    TdPsolaConfig config;
    TdPsolaStats stats;
    TdPsola_DefaultConfig(&config);
    config.strength = 1.0f;
    TEST_ASSERT_EQUAL_INT(TD_PSOLA_STATUS_OK,
                          TdPsola_ProcessBuffer(input_buffer, output_buffer,
                                                TEST_SAMPLES, &config, &stats));
    const float measured = measure_pitch(output_buffer + TEST_SAMPLE_RATE / 2U,
                                         TEST_SAMPLES - TEST_SAMPLE_RATE / 2U);
    TEST_ASSERT_FLOAT_WITHIN(4.0f, 440.0f, measured);
    TEST_ASSERT_TRUE(stats.voiced_frames > 0U);
}

static void test_OutputDoesNotContainHugeDiscontinuitiesOnSteadyTone(void)
{
    generate_harmonic_voice(445.0f);
    TEST_ASSERT_EQUAL_INT(TD_PSOLA_STATUS_OK,
                          TdPsola_ProcessBuffer(input_buffer, output_buffer,
                                                TEST_SAMPLES, NULL, NULL));
    TEST_ASSERT_LESS_THAN_INT(16000, max_adjacent_jump(output_buffer, TEST_SAMPLES));
}

static void test_InvalidConfigurationIsRejected(void)
{
    generate_harmonic_voice(445.0f);
    TdPsolaConfig config;
    TdPsola_DefaultConfig(&config);
    config.strength = 1.5f;
    TEST_ASSERT_EQUAL_INT(TD_PSOLA_STATUS_INVALID_CONFIG,
                          TdPsola_ProcessBuffer(input_buffer, output_buffer,
                                                TEST_SAMPLES, &config, NULL));
}

int main(void)
{
    UNITY_BEGIN();
    RUN_TEST(test_ChromaticTargetMaps445To440);
    RUN_TEST(test_SilenceRemainsSilent);
    RUN_TEST(test_445HzVoiceMovesToward440);
    RUN_TEST(test_OutputDoesNotContainHugeDiscontinuitiesOnSteadyTone);
    RUN_TEST(test_InvalidConfigurationIsRejected);
    return UNITY_END();
}
